{
  "schemaVersion": "0.2",
  "slug": "marketing-site",
  "name": "Marketing site",
  "status": "experimental",
  "purpose": "Hero, pricing cards, and FAQ accordion for a marketing landing fragment.",
  "scenarios": [
    "Introduce a product with a hero call to action",
    "Compare three pricing plans",
    "Expand FAQ answers in an accordion"
  ],
  "props": {
    "locale": {
      "type": "string",
      "required": false,
      "description": "BCP 47 locale for bundled block copy.",
      "default": "en"
    },
    "onCta": {
      "type": "event",
      "required": false,
      "description": "Called when a hero or plan call to action is activated."
    }
  },
  "variants": [
    {
      "name": "density",
      "values": ["comfortable", "compact"],
      "default": "comfortable",
      "description": "Inherits density from token rungs rather than a local viewport query."
    }
  ],
  "states": [
    { "name": "default", "description": "Hero, pricing, and FAQ are visible." }
  ],
  "composition": {
    "allowedParents": ["page"],
    "allowedChildren": ["typography", "button", "accordion", "card"],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not restyle this block with raw left/right CSS.",
    "Do not claim 21 authored languages; 19 locales are ICU skeletons."
  ],
  "a11y": {
    "role": "article",
    "keyboard": ["Tab reaches CTAs and FAQ triggers", "Enter or Space expands a FAQ item"],
    "focus": "Actions stay in document order with a visible focus ring.",
    "labeling": "Pricing and FAQ sections have headings; accordion triggers name the question.",
    "wcag": ["2.1.1", "2.4.7", "4.1.2"]
  },
  "responsive": {
    "strategy": "Pricing uses @container with the tablet rem token; no viewport media queries.",
    "breakpoints": {
      "compact": "Plans stack to one column.",
      "medium": "Plans become three columns at 48rem container inline-size.",
      "large": "Plans remain three columns."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction comes from locale language.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "marketing-site",
    "states": ["default"],
    "intents": ["browse-pricing"]
  }
}

{
  "slug": "marketing-site",
  "type": "registry:block",
  "name": "Marketing site",
  "dependencies": ["accordion", "button", "card", "typography"],
  "theme": { "constraints": [] },
  "rtl": true,
  "platforms": {
    "compact": true,
    "medium": true,
    "large": true
  },
  "preview": {
    "width": 1280,
    "title": "Hero, pricing, and FAQ"
  }
}

.cu-block-marketing-site {
  container-type: inline-size;
  container-name: marketing;
  display: grid;
  gap: calc(var(--cu-space-3) * 2);
  padding-block: var(--cu-space-3);
  padding-inline: var(--cu-space-3);
}

.cu-block-marketing-site__hero,
.cu-block-marketing-site__pricing,
.cu-block-marketing-site__faq {
  display: grid;
  gap: var(--cu-space-3);
}

.cu-block-marketing-site__meta {
  margin-block: 0;
  color: var(--cu-color-fg-default);
  font-size: var(--cu-typography-size-caption);
}

.cu-block-marketing-site__plans {
  display: grid;
  gap: var(--cu-space-3);
  grid-template-columns: 1fr;
}

.cu-block-marketing-site__plans > * {
  display: grid;
  gap: var(--cu-space-2);
}

@container marketing (min-inline-size: 48rem) {
  .cu-block-marketing-site__plans {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
